    b.BackgroundColor3=col
    b.Text=text
    b.TextColor3=Color3.new(1,1,1)
    b.Font=Enum.Font.GothamBold
    b.TextSize=11
    b.Parent=main
    Instance.new("UICorner", b).CornerRadius=UDim.new(0,8)
    return b
end

local recBtn = btn("● REC", 60, Color3.fromRGB(220,50,50))
local stopBtn = btn("■ STOP", 92, Color3.fromRGB(70,70,70))
local playBtn = btn("▶ PLAY ME", 124, Color3.fromRGB(50,120,220))
local resetBtn = btn("🗑 RESET RECORDING", 156, Color3.fromRGB(180,40,40))
local exportBtn = btn("📄 COPY + SAVE EXPORT", 188, Color3.fromRGB(40,160,80))
local saveFileBtn = btn("💾 SAVE TO FILE ONLY", 220, Color3.fromRGB(80,80,200))

local dragging, dragStart, startPos
title.InputBegan:Connect(function(i) if i.UserInputType==Enum.UserInputType.MouseButton1 then dragging=true dragStart=i.Position startPos=main.Position end end)
UserInputService.InputChanged:Connect(function(i) if dragging and i.UserInputType==Enum.UserInputType.MouseMovement then local d=i.Position-dragStart main.Position=UDim2.new(startPos.X.Scale,startPos.X.Offset+d.X,startPos.Y.Scale,startPos.Y.Offset+d.Y) end end)
UserInputService.InputEnded:Connect(function() dragging=false end)

local function getMotors(char)
    local m = {}
    for _, v in ipairs(char:GetDescendants()) do if v:IsA("Motor6D") then table.insert(m, v) end end
    table.sort(m, function(a,b) return a.Name < b.Name end)
    return m
end
local function getMotorMap(char)
    local map = {}
    for _, v in ipairs(char:GetDescendants()) do if v:IsA("Motor6D") then map[v.Name] = v end end
    return map
end

local function resetRecording()
    if recordConn then recordConn:Disconnect() recordConn=nil end
    if playConn then playConn:Disconnect() playConn=nil end
    recordedData = {}
    local char = player.Character
    if char then
        local hum = char:FindFirstChildOfClass("Humanoid")
        local hrp = char:FindFirstChild("HumanoidRootPart")
        if hrp then hrp.Anchored = false hrp.AssemblyLinearVelocity = Vector3.zero hrp.AssemblyAngularVelocity = Vector3.zero end
        if hum then hum.PlatformStand = false hum.AutoRotate = true hum.EvaluateStateMachine = true if not hum:FindFirstChildOfClass("Animator") then Instance.new("Animator", hum) end hum:ChangeState(Enum.HumanoidStateType.Running) end
        for _, v in ipairs(char:GetDescendants()) do if v:IsA("BasePart") then v.CanCollide = (v.Name ~= "HumanoidRootPart") end end
    end
    isRecording = false isPlaying = false
    recBtn.Text = "● REC" playBtn.Text = "▶ PLAY ME" status.Text = "🗑 Reset - No data"
end

local function stopAll()
    if recordConn then recordConn:Disconnect() recordConn=nil end
    if playConn then playConn:Disconnect() playConn=nil end
    local char = player.Character
    if char then
        local hum = char:FindFirstChildOfClass("Humanoid")
        local hrp = char:FindFirstChild("HumanoidRootPart")
        if hrp then hrp.Anchored = false hrp.AssemblyLinearVelocity = Vector3.zero hrp.AssemblyAngularVelocity = Vector3.zero end
        if hum then hum.PlatformStand = false hum.AutoRotate = true hum.EvaluateStateMachine = true if not hum:FindFirstChildOfClass("Animator") then Instance.new("Animator", hum) end hum:ChangeState(Enum.HumanoidStateType.Running) end
        for _, v in ipairs(char:GetDescendants()) do if v:IsA("BasePart") then v.CanCollide = (v.Name ~= "HumanoidRootPart") end end
    end
    isRecording = false isPlaying = false
    recBtn.Text = "● REC" playBtn.Text = "▶ PLAY ME" status.Text = "Stopped"
end

local function startRec()
    if isRecording or isPlaying then return end
    local char = player.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return end
    local motors = getMotors(char)
    recordedData = {} isRecording = true status.Text = "🔴 RECORDING" recBtn.Text = "● RECORDING..."
    local startTime = tick()
    recordConn = RunService.Heartbeat:Connect(function()
        local transforms = table.create(#motors)
        for i, m in ipairs(motors) do transforms[i] = m.Transform end
        table.insert(recordedData, {t = tick() - startTime, hrp = hrp.CFrame, motors = transforms})
        if #recordedData % 30 == 0 then status.Text = "🔴 "..#recordedData.." frames" end
    end)
end

local function playMe()
    if #recordedData == 0 then status.Text="No data" return end
    if isRecording or isPlaying then return end
    local char = player.Character
    if not char then return end
    local hrp = char:FindFirstChild("HumanoidRootPart")
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hrp or not hum then return end
    local motors = getMotors(char)
    local motorMap = getMotorMap(char)

    local startHrp = hrp.CFrame
    local startPos = startHrp.Position
    local firstFrame = recordedData[1]
    local endPos = firstFrame.hrp.Position
    local targetCF = firstFrame.hrp
    local dist = (endPos - startPos).Magnitude
    local shouldWalk = dist > 2

    local anim = hum:FindFirstChildOfClass("Animator")
    if anim then anim:Destroy() end
    hum.EvaluateStateMachine = false
    hum.PlatformStand = true
    hum.AutoRotate = false
    hum:ChangeState(Enum.HumanoidStateType.Physics)
    hrp.Anchored = false
    for _, v in ipairs(char:GetDescendants()) do if v:IsA("BasePart") then v.CanCollide = false end end

    isPlaying = true
    playBtn.Text = "▶ REPLAYING YOU..."

    local walkSpeed = hum.WalkSpeed
    if walkSpeed <= 0 then walkSpeed = 16 end

    local flatDir = Vector3.new(endPos.X - startPos.X, 0, endPos.Z - startPos.Z)
    local facingCF = startHrp
    if flatDir.Magnitude > 0.1 then facingCF = CFrame.lookAt(startPos, startPos + flatDir) end
    local _, startYaw, _ = startHrp:ToEulerAnglesYXZ()
    local _, targetYaw, _ = facingCF:ToEulerAnglesYXZ()
    local yawDiff = math.abs((targetYaw - startYaw + math.pi) % (2*math.pi) - math.pi)
    local initialRotateDuration = math.clamp(yawDiff / math.rad(400) * 0.25 + 0.05, 0.05, 0.25)

    local walkFrames = WALK_CYCLE.frames
    local walkMotorNames = WALK_CYCLE.motorNames
    local walkCycleDuration = walkFrames[#walkFrames].t - walkFrames[1].t
    local pauseDuration = 0.4
    local loopDuration = walkCycleDuration + pauseDuration
    if walkCycleDuration <= 0 then walkCycleDuration = 1 end

    local totalMoveTime = dist / walkSpeed
    if totalMoveTime < 0.1 then totalMoveTime = 0.1 end

    local phase = shouldWalk and "initialRotate" or "reached"
    local phaseStart = tick()
    local rotateStartCF = startHrp
    local finalRotateStartCF = nil
    local playStart = 0
    local index = 1
    local total = #recordedData
    local reachedPauseUntil = 0

    if shouldWalk then status.Text = "1️⃣ Rotating to face first pos..." end

    playConn = RunService.Heartbeat:Connect(function()
        if phase == "initialRotate" then
            local elapsed = tick() - phaseStart
            local alpha = math.clamp(elapsed / initialRotateDuration, 0, 1)
            local smooth = (1 - math.cos(alpha * math.pi)) * 0.5
            hrp.CFrame = rotateStartCF:Lerp(facingCF, smooth)
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
            if alpha >= 1 then
                phase = "walk"
                phaseStart = tick()
                status.Text = "2️⃣ Walking at WalkSpeed "..math.floor(walkSpeed)
            end
            return
        end

        if phase == "walk" then
            local elapsed = tick() - phaseStart
            local loopIndex = math.floor(elapsed / loopDuration)
            local loopElapsed = elapsed % loopDuration
            local moveTimeBefore = loopIndex * walkCycleDuration
            local movingElapsed
            local isPaused = false
            if loopElapsed < walkCycleDuration then
                movingElapsed = moveTimeBefore + loopElapsed
            else
                movingElapsed = moveTimeBefore + walkCycleDuration
                isPaused = true
            end
            local alpha = math.clamp(movingElapsed / totalMoveTime, 0, 1)
            local lerpedPos = startPos:Lerp(endPos, alpha)
            local dir = endPos - lerpedPos
            local flat = Vector3.new(dir.X, 0, dir.Z)
            local curCF
            if flat.Magnitude > 0.1 then
                curCF = CFrame.lookAt(lerpedPos, lerpedPos + flat)
            else
                curCF = CFrame.new(lerpedPos) * (facingCF - facingCF.Position)
            end
            hrp.CFrame = curCF
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero

            if not isPaused then
                local cycleTime = walkFrames[1].t + loopElapsed
                local wIdx = 1
                while wIdx < #walkFrames and walkFrames[wIdx+1].t <= cycleTime do wIdx += 1 end
                local currW = walkFrames[wIdx]
                local nextW = walkFrames[wIdx+1] or walkFrames[1]
                local wAlpha = 0
                if nextW.t ~= currW.t then wAlpha = math.clamp((cycleTime - currW.t)/(nextW.t - currW.t),0,1) end
                for j, mName in ipairs(walkMotorNames) do
                    local motorObj = motorMap[mName]
                    if motorObj and currW.motors[j] and nextW.motors[j] then
                        motorObj.Transform = currW.motors[j]:Lerp(nextW.motors[j], wAlpha)
                    end
                end
            else
                local idle = walkFrames[1]
                for j, mName in ipairs(walkMotorNames) do
                    local motorObj = motorMap[mName]
                    if motorObj and idle.motors[j] then motorObj.Transform = idle.motors[j] end
                end
                status.Text = "⏸️ Paused (stop anim + stop move)"
            end

            if alpha >= 1 then
                phase = "reached"
                reachedPauseUntil = tick() + 0.5
                hrp.CFrame = CFrame.new(endPos) * (hrp.CFrame - hrp.CFrame.Position)
                hrp.AssemblyLinearVelocity = Vector3.zero
                hrp.AssemblyAngularVelocity = Vector3.zero
                status.Text = "📍 Reached - locking exact pos"
            end
            return
        end

        if phase == "reached" then
            hrp.CFrame = CFrame.new(endPos) * (hrp.CFrame - hrp.CFrame.Position)
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
            local idle = walkFrames[1]
            for j, mName in ipairs(walkMotorNames) do
                local motorObj = motorMap[mName]
                if motorObj and idle.motors[j] then motorObj.Transform = idle.motors[j] end
            end
            if tick() >= reachedPauseUntil then
                phase = "finalRotate"
                phaseStart = tick()
                finalRotateStartCF = hrp.CFrame
                status.Text = "4️⃣ Rotating to first frame rotation..."
            else
                status.Text = "⏸️ Stopped moving/idle at first pos"
            end
            return
        end

        if phase == "finalRotate" then
            local elapsed = tick() - phaseStart
            local _, sYaw, _ = finalRotateStartCF:ToEulerAnglesYXZ()
            local _, tYaw, _ = targetCF:ToEulerAnglesYXZ()
            local yawDiff2 = math.abs((tYaw - sYaw + math.pi) % (2*math.pi) - math.pi)
            local rotateDur = math.clamp(yawDiff2 / math.rad(350) * 0.25 + 0.08, 0.08, 0.35)
            local alpha = math.clamp(elapsed / rotateDur, 0, 1)
            local smooth = (1 - math.cos(alpha * math.pi)) * 0.5
            local newCF = finalRotateStartCF:Lerp(targetCF, smooth)
            hrp.CFrame = CFrame.new(endPos) * (newCF - newCF.Position)
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
            if alpha >= 1 then
                hrp.CFrame = targetCF
                phase = "replay"
                playStart = tick()
                index = 1
                status.Text = "▶ Begins recording playback"
            end
            return
        end

        local elapsed = tick() - playStart
        while index < total and recordedData[index + 1].t <= elapsed do index += 1 end
        local curr = recordedData[index]
        local nextF = recordedData[index + 1]
        if curr and nextF then
            local alpha = math.clamp((elapsed - curr.t) / (nextF.t - curr.t), 0, 1)
            hrp.CFrame = curr.hrp:Lerp(nextF.hrp, alpha)
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
            for i, m in ipairs(motors) do if m.Parent then m.Transform = curr.motors[i]:Lerp(nextF.motors[i], alpha) end end
        elseif curr then
            hrp.CFrame = curr.hrp
            for i, m in ipairs(motors) do if m.Parent then m.Transform = curr.motors[i] end end
        end
        if elapsed >= recordedData[total].t then stopAll() status.Text = "✅ Done" end
    end)
end

recBtn.MouseButton1Click:Connect(startRec)
stopBtn.MouseButton1Click:Connect(stopAll)
playBtn.MouseButton1Click:Connect(playMe)
resetBtn.MouseButton1Click:Connect(resetRecording)

local function exportBoth()
    if #recordedData == 0 then status.Text = "No data" return end
    status.Text = "📄 Exporting "..#recordedData.." frames..."
    local function cfStr(cf)
        local x,y,z,r00,r01,r02,r10,r11,r12,r20,r21,r22 = cf:GetComponents()
        return string.format("CFrame.new(%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f)",x,y,z,r00,r01,r02,r10,r11,r12,r20,r21,r22)
    end
    local out = {}
    table.insert(out, "-- Exported "..#recordedData.." frames")
    table.insert(out, "local Players = game:GetService('Players') local RunService = game:GetService('RunService') local player = Players.LocalPlayer")
    table.insert(out, "local function getMotors(c) local m={} for _,v in ipairs(c:GetDescendants()) do if v:IsA('Motor6D') then table.insert(m,v) end end table.sort(m,function(a,b) return a.Name<b.Name end) return m end")
    table.insert(out, "local data = {")
    for i,f in ipairs(recordedData) do
        local ms = {}
        for _,c in ipairs(f.motors) do table.insert(ms, cfStr(c)) end
        table.insert(out, string.format("{t=%.3f,hrp=%s,motors={%s}},", f.t, cfStr(f.hrp), table.concat(ms, ",")))
        if i % 100 == 0 then RunService.Heartbeat:Wait() end
    end
    table.insert(out, "}")
    table.insert(out, "local char = player.Character or player.CharacterAdded:Wait() local hrp = char:WaitForChild('HumanoidRootPart') local hum = char:WaitForChild('Humanoid') local motors = getMotors(char)")
    table.insert(out, "local anim = hum:FindFirstChildOfClass('Animator') if anim then anim:Destroy() end hum.EvaluateStateMachine=false hum.PlatformStand=true hum.AutoRotate=false for _,v in ipairs(char:GetDescendants()) do if v:IsA('BasePart') then v.CanCollide=false end end")
    table.insert(out, "local s=tick() local idx=1 local tot=#data local con con=RunService.Heartbeat:Connect(function() local e=tick()-s while idx<tot and data[idx+1].t<=e do idx+=1 end local cur=data[idx] local nxt=data[idx+1] if cur and nxt then local a=math.clamp((e-cur.t)/(nxt.t-cur.t),0,1) hrp.CFrame=cur.hrp:Lerp(nxt.hrp,a) for i,m in ipairs(motors) do if m.Parent then m.Transform=cur.motors[i]:Lerp(nxt.motors[i],a) end end elseif cur then hrp.CFrame=cur.hrp for i,m in ipairs(motors) do if m.Parent then m.Transform=cur.motors[i] end end end if e>=data[tot].t then con:Disconnect() hrp.Anchored=false hum.PlatformStand=false hum.AutoRotate=true hum.EvaluateStateMachine=true end end)")
    local full = table.concat(out, "\n")
    local path = "exported_"..#recordedData.."frames.lua"
    if writefile then pcall(function() writefile(path, full) end) end
    if setclipboard then pcall(function() setclipboard(full) end) status.Text = "✅ COPIED + SAVED: "..path else status.Text = "✅ SAVED: "..path end
end

