local function exportBoth()
    if #recordedData == 0 then status.Text = "No data" return end
    status.Text = "📄 Exporting "..#recordedData.." frames..."
    local function cfStr(cf)
        local x,y,z,r00,r01,r02,r10,r11,r12,r20,r21,r22 = cf:GetComponents()
        return string.format("CFrame.new(%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f)",x,y,z,r00,r01,r02,r10,r11,r12,r20,r21,r22)
    end
    local out = {}
    table.insert(out, "-- Exported "..#recordedData.." frames")
    table.insert(out, "local Players = game:GetService('Players') local RunService = game:GetService('RunService') local player = Players.LocalPlayer")
    table.insert(out, "local function getMotors(c) local m={} for _,v in ipairs(c:GetDescendants()) do if v:IsA('Motor6D') then table.insert(m,v) end end table.sort(m,function(a,b) return a.Name<b.Name end) return m end")
    table.insert(out, "local data = {")
    for i,f in ipairs(recordedData) do
        local ms = {}
        for _,c in ipairs(f.motors) do table.insert(ms, cfStr(c)) end
        table.insert(out, string.format("{t=%.3f,hrp=%s,motors={%s}},", f.t, cfStr(f.hrp), table.concat(ms, ",")))
        if i % 100 == 0 then RunService.Heartbeat:Wait() end
    end
    table.insert(out, "}")
    table.insert(out, "local char = player.Character or player.CharacterAdded:Wait() local hrp = char:WaitForChild('HumanoidRootPart') local hum = char:WaitForChild('Humanoid') local motors = getMotors(char)")
    table.insert(out, "local anim = hum:FindFirstChildOfClass('Animator') if anim then anim:Destroy() end hum.EvaluateStateMachine=false hum.PlatformStand=true hum.AutoRotate=false for _,v in ipairs(char:GetDescendants()) do if v:IsA('BasePart') then v.CanCollide=false end end")
    table.insert(out, "local s=tick() local idx=1 local tot=#data local con con=RunService.Heartbeat:Connect(function() local e=tick()-s while idx<tot and data[idx+1].t<=e do idx+=1 end local cur=data[idx] local nxt=data[idx+1] if cur and nxt then local a=math.clamp((e-cur.t)/(nxt.t-cur.t),0,1) hrp.CFrame=cur.hrp:Lerp(nxt.hrp,a) for i,m in ipairs(motors) do if m.Parent then m.Transform=cur.motors[i]:Lerp(nxt.motors[i],a) end end elseif cur then hrp.CFrame=cur.hrp for i,m in ipairs(motors) do if m.Parent then m.Transform=cur.motors[i] end end end if e>=data[tot].t then con:Disconnect() hrp.Anchored=false hum.PlatformStand=false hum.AutoRotate=true hum.EvaluateStateMachine=true end end)")
    local full = table.concat(out, "\n")
    local path = "exported_"..#recordedData.."frames.lua"
    if writefile then pcall(function() writefile(path, full) end) end
    if setclipboard then pcall(function() setclipboard(full) end) status.Text = "✅ COPIED + SAVED: "..path else status.Text = "✅ SAVED: "..path end
end

