-- Auto-start logic (same as main script Play button)
local char = player.Character or player.CharacterAdded:Wait()
local hrp = char:WaitForChild('HumanoidRootPart')
local hum = char:WaitForChild('Humanoid')
local motors = getMotors(char)

-- Save initial
local initialHrpCF = hrp.CFrame
local initialMotors = {}
for _, m in ipairs(motors) do initialMotors[m.Name] = m.Transform end

local anim = hum:FindFirstChildOfClass('Animator')
if anim then anim:Destroy() end
hum.EvaluateStateMachine = false
hum.PlatformStand = true
hum.AutoRotate = false
for _,v in ipairs(char:GetDescendants()) do if v:IsA('BasePart') then v.CanCollide = false end end

local walkFrames = WALK_CYCLE.frames
local walkMotorNames = WALK_CYCLE.motorNames

local motorMap = {}
for _, m in ipairs(motors) do motorMap[m.Name] = m end

local walkSpeed = hum.WalkSpeed
if walkSpeed <= 0 then walkSpeed = 16 end

local startPos = hrp.Position
local startHrp = hrp.CFrame
local targetCF = data[1].hrp
local endPos = targetCF.Position

local dirVec = endPos - startPos
dirVec = Vector3.new(dirVec.X, 0, dirVec.Z)
local dist = dirVec.Magnitude
local shouldWalk = dist > 1

local facingCF
if dirVec.Magnitude > 0.1 then
    facingCF = CFrame.lookAt(startPos, startPos + dirVec)
else
    facingCF = startHrp
end

local _, sYaw, _ = startHrp:ToEulerAnglesYXZ()
local _, tYaw, _ = facingCF:ToEulerAnglesYXZ()
local yawDiff = math.abs((tYaw - sYaw + math.pi) % (2*math.pi) - math.pi)
local initialRotateDuration = math.clamp(yawDiff / math.rad(350) * 0.25 + 0.08, 0.08, 0.35)

local totalDur = walkFrames[#walkFrames].t
local walkCycleDuration = 0
for i=2,#walkFrames do
    local dt = walkFrames[i].t - walkFrames[i-1].t
    if dt > 0.05 then walkCycleDuration += walkFrames[i-1].t end
end
if walkCycleDuration <= 0 then walkCycleDuration = totalDur * 0.7 end
local pauseDuration = totalDur - walkCycleDuration
if pauseDuration < 0 then pauseDuration = 0 end
local loopDuration = totalDur
if walkCycleDuration <= 0 then walkCycleDuration = 1 end
local totalMoveTime = dist / walkSpeed
if totalMoveTime < 0.1 then totalMoveTime = 0.1 end

local phase = shouldWalk and "initialRotate" or "reached"
local phaseStart = tick()
local rotateStartCF = startHrp
local finalRotateStartCF = nil
local playStart = 0
local index = 1
local total = #data
local reachedPauseUntil = 0

print("1️⃣ Rotating to face first pos...")

local con
con = RunService.Heartbeat:Connect(function()
    if phase == "initialRotate" then
        local elapsed = tick() - phaseStart
        local alpha = math.clamp(elapsed / initialRotateDuration, 0, 1)
        local smooth = (1 - math.cos(alpha * math.pi)) * 0.5
        hrp.CFrame = rotateStartCF:Lerp(facingCF, smooth)
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
        if alpha >= 1 then
            phase = "walk"
            phaseStart = tick()
            print("2️⃣ Walking at WalkSpeed "..math.floor(walkSpeed))
        end
        return
    end

    if phase == "walk" then
        local elapsed = tick() - phaseStart
        local loopIndex = math.floor(elapsed / loopDuration)
        local loopElapsed = elapsed % loopDuration
        local moveTimeBefore = loopIndex * walkCycleDuration
        local movingElapsed
        local isPaused = false
        if loopElapsed < walkCycleDuration then
            movingElapsed = moveTimeBefore + loopElapsed
        else
            movingElapsed = moveTimeBefore + walkCycleDuration
            isPaused = true
        end
        local alpha = math.clamp(movingElapsed / totalMoveTime, 0, 1)
        local lerpedPos = startPos:Lerp(endPos, alpha)
        local dir = endPos - lerpedPos
        local flat = Vector3.new(dir.X, 0, dir.Z)
        local curCF
        if flat.Magnitude > 0.1 then
            curCF = CFrame.lookAt(lerpedPos, lerpedPos + flat)
        else
            curCF = CFrame.new(lerpedPos) * (facingCF - facingCF.Position)
        end
        hrp.CFrame = curCF
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero

        if not isPaused then
            local cycleTime = walkFrames[1].t + loopElapsed
            local wIdx = 1
            while wIdx < #walkFrames and walkFrames[wIdx+1].t <= cycleTime do wIdx += 1 end
            local currW = walkFrames[wIdx]
            local nextW = walkFrames[wIdx+1] or walkFrames[1]
            local wAlpha = 0
            if nextW.t ~= currW.t then wAlpha = math.clamp((cycleTime - currW.t)/(nextW.t - currW.t),0,1) end
            for j, mName in ipairs(walkMotorNames) do
                local motorObj = motorMap[mName]
                if motorObj and currW.motors[j] and nextW.motors[j] then
                    motorObj.Transform = currW.motors[j]:Lerp(nextW.motors[j], wAlpha)
                end
            end
        else
            local idle = walkFrames[1]
            for j, mName in ipairs(walkMotorNames) do
                local motorObj = motorMap[mName]
                if motorObj and idle.motors[j] then motorObj.Transform = idle.motors[j] end
            end
        end

        if alpha >= 1 then
            phase = "reached"
            reachedPauseUntil = tick() + 0.5
            hrp.CFrame = CFrame.new(endPos) * (hrp.CFrame - hrp.CFrame.Position)
            print("📍 Reached - locking exact pos")
        end
        return
    end

    if phase == "reached" then
        hrp.CFrame = CFrame.new(endPos) * (hrp.CFrame - hrp.CFrame.Position)
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
        local idle = walkFrames[1]
        for j, mName in ipairs(walkMotorNames) do
            local motorObj = motorMap[mName]
            if motorObj and idle.motors[j] then motorObj.Transform = idle.motors[j] end
        end
        if tick() >= reachedPauseUntil then
            phase = "finalRotate"
            phaseStart = tick()
            finalRotateStartCF = hrp.CFrame
            print("4️⃣ Rotating to first frame rotation...")
        end
        return
    end

    if phase == "finalRotate" then
        local elapsed = tick() - phaseStart
        local _, sYaw2, _ = finalRotateStartCF:ToEulerAnglesYXZ()
        local _, tYaw2, _ = targetCF:ToEulerAnglesYXZ()
        local yawDiff2 = math.abs((tYaw2 - sYaw2 + math.pi) % (2*math.pi) - math.pi)
        local rotateDur = math.clamp(yawDiff2 / math.rad(350) * 0.25 + 0.08, 0.08, 0.35)
        local alpha = math.clamp(elapsed / rotateDur, 0, 1)
        local smooth = (1 - math.cos(alpha * math.pi)) * 0.5
        local newCF = finalRotateStartCF:Lerp(targetCF, smooth)
        hrp.CFrame = CFrame.new(endPos) * (newCF - newCF.Position)
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
        if alpha >= 1 then
            hrp.CFrame = targetCF
            phase = "replay"
            playStart = tick()
            index = 1
            print("▶ Begins recording playback")
        end
        return
    end

    -- REPLAY PHASE (your recorded data)
    local elapsed = tick() - playStart
    while index < total and data[index + 1].t <= elapsed do index += 1 end
    local curr = data[index]
    local nextF = data[index + 1]
    if curr and nextF then
        local alpha = math.clamp((elapsed - curr.t) / (nextF.t - curr.t), 0, 1)
        hrp.CFrame = curr.hrp:Lerp(nextF.hrp, alpha)
        hrp.AssemblyLinearVelocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
        for i, m in ipairs(motors) do if m.Parent then m.Transform = curr.motors[i]:Lerp(nextF.motors[i], alpha) end end
    elseif curr then
        hrp.CFrame = curr.hrp
        for i, m in ipairs(motors) do if m.Parent then m.Transform = curr.motors[i] end end
    end
    if elapsed >= data[total].t then
        con:Disconnect()
        hrp.Anchored = false
        hum.PlatformStand = false
        hum.AutoRotate = true
        hum.EvaluateStateMachine = true
        for name, cf in pairs(initialMotors) do
            local m = motorMap[name]
            if m then m.Transform = cf end
        end
        print("✅ Done")
    end
end)
